-- Large deterministic test-data dataset for the Underdogs PostgreSQL database
-- Requires the existing tables: users, teams, tournaments, players, matches, bets
-- Safe to run more than once: duplicate rows are skipped with ON CONFLICT DO NOTHING.

SET search_path TO public;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

SELECT setval(
    pg_get_serial_sequence('public.users', 'technical_id'),
    COALESCE((SELECT MAX(technical_id) FROM public.users), 1),
    true
);

SELECT setval(
    pg_get_serial_sequence('public.teams', 'technical_id'),
    COALESCE((SELECT MAX(technical_id) FROM public.teams), 1),
    true
);

SELECT setval(
    pg_get_serial_sequence('public.tournaments', 'technical_id'),
    COALESCE((SELECT MAX(technical_id) FROM public.tournaments), 1),
    true
);

SELECT setval(
    pg_get_serial_sequence('public.players', 'technical_id'),
    COALESCE((SELECT MAX(technical_id) FROM public.players), 1),
    true
);

SELECT setval(
    pg_get_serial_sequence('public.matches', 'technical_id'),
    COALESCE((SELECT MAX(technical_id) FROM public.matches), 1),
    true
);

SELECT setval(
    pg_get_serial_sequence('public.bets', 'technical_id'),
    COALESCE((SELECT MAX(technical_id) FROM public.bets), 1),
    true
);


